    /^[[:space:]]*#/ {next}
    NF==2 {
        gsub(/"/, "\\\"", $2);
        printf "\"%s\":\"%s\",", $1, $2
    }
' .env.test)
# Remove trailing comma and wrap with braces
json_payload="{${json_payload%,}}"

# Send the config JSON to the deployment orchestrator (audit compliance)
curl -s -X POST -H "Content-Type: application/json" -d "$json_payload" http://localhost:47301/api/deploy-config

